import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("correction limit", () => {
  test("correction limit", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "50.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    await ui.refresh(pg_uma);
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "-30.00", "corrects": "FY2026-1"}));
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    expect(await ui.addClaim(pg_uma, p_ada, {"amount": "-20.01", "corrects": "FY2026-1"})).toBeNull();
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "-20.00", "corrects": "FY2026-1"}));
    expect(await ui.addClaim(pg_uma, p_ada, {"amount": "-0.01", "corrects": "FY2026-1"})).toBeNull();
    expect(await ui.claimAction(pg_uma, c_ada_2, "void")).toBe(true);
    const c_ada_3 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "-20.00", "corrects": "FY2026-1"}));
    expect(await ui.claimAction(pg_uma, c_ada_3, "open")).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ada_1, "settle")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_3, "settle")).toBe(true);
