/** Orders rates by grade, then from-date with no from-date first. */
function byGradeThenFrom(a: RateView, b: RateView): number {
  if (a.grade !== b.grade) return a.grade < b.grade ? -1 : 1;
  return (a.from ?? '').localeCompare(b.from ?? '');
}

